using System.Net;using System.Net.Http.Json;using System.Net.WebSockets;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Diagnostics;using Nexora.Remote;
internal static class EngineLoopbackValidation{
 public static async Task<object?> Run(Form form,TextBox target,Panel marker,Button button){string? address=Environment.GetEnvironmentVariable("NEXORA_TEST_BACKEND");if(address==null)return null;var baseUri=new Uri(address);if(!baseUri.IsLoopback)throw new InvalidOperationException("Validation backend must be loopback");using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(50));var ct=timeout.Token;var cookies=new CookieContainer();using var handler=new HttpClientHandler{CookieContainer=cookies};using var http=new HttpClient(handler){BaseAddress=baseUri};http.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:5173");
 async Task<JsonElement> Post(string path,object body){using var r=await http.PostAsJsonAsync(path,body,ct);r.EnsureSuccessStatusCode();return await r.Content.ReadFromJsonAsync<JsonElement>(ct);}
 async Task<JsonElement> Get(string path){using var r=await http.GetAsync(path,ct);r.EnsureSuccessStatusCode();return await r.Content.ReadFromJsonAsync<JsonElement>(ct);}
 async Task Wait(Func<Task<bool>> condition){var watch=Stopwatch.StartNew();while(!await condition()){if(watch.Elapsed.TotalSeconds>15)throw new TimeoutException("Loopback engine condition failed");await Task.Delay(50,ct);}}
 await Post("/api/auth/login",new{email="e2e@example.test",password="E2E-Only-Password!42"});var org=(await Get("/api/organizations"))[0].GetProperty("id").GetString()!;http.DefaultRequestHeaders.Add("X-Organization-Id",org);var enrollment=await Post("/api/enrollments",new{});using var rsa=RSA.Create(3072);var registered=await Post("/api/agent/enroll",new{organizationId=org,token=enrollment.GetProperty("token").GetString(),name="AUTHORIZED WINDOWS LOOPBACK TEST",publicKey=rsa.ExportSubjectPublicKeyInfoPem(),os=Environment.OSVersion.VersionString,version="0.2.0-test"});string device=registered.GetProperty("id").GetString()!;var identity=new Identity(address,org,device,rsa.ExportPkcs8PrivateKeyPem(),registered.GetProperty("serverPublicKey").GetString()!);
 using var engineStop=new CancellationTokenSource();using var engine=new Engine(identity,_=>{});var engineTask=Task.Run(()=>engine.Run(engineStop.Token));
 async Task<bool> Online(){var devices=await Get("/api/devices");return devices.EnumerateArray().Any(d=>d.GetProperty("id").GetString()==device&&d.GetProperty("online").GetBoolean()&&d.GetProperty("desktopStatus").GetString()=="available");}
 async Task<(ClientWebSocket Socket,string Id)> OpenViewer(){var session=await Post("/api/sessions",new{deviceId=device,mode="control"});string sid=session.GetProperty("id").GetString()!;var ticket=await Post("/api/sessions/"+sid+"/ticket",new{});var ws=new ClientWebSocket();ws.Options.Cookies=cookies;ws.Options.SetRequestHeader("Origin","http://127.0.0.1:5173");ws.Options.AddSubProtocol("nexora.v2");ws.Options.AddSubProtocol("ticket."+ticket.GetProperty("ticket").GetString());await ws.ConnectAsync(new UriBuilder(baseUri){Scheme="ws",Path="/api/socket"}.Uri,ct);return(ws,sid);}
 async Task<byte[]> Frame(ClientWebSocket ws,int? width=null){var buffer=new byte[65536];while(true){using var bytes=new MemoryStream();WebSocketReceiveResult result;do{result=await ws.ReceiveAsync(new ArraySegment<byte>(buffer),ct);if(result.MessageType==WebSocketMessageType.Close)throw new IOException("Viewer closed before frame");bytes.Write(buffer,0,result.Count);if(bytes.Length>2097152)throw new InvalidDataException("Frame limit");}while(!result.EndOfMessage);if(result.MessageType!=WebSocketMessageType.Binary)continue;var frame=bytes.ToArray();using var image=new Bitmap(new MemoryStream(frame));if(width==null||image.Width==width)return frame;}}
 async Task Send(ClientWebSocket ws,object value)=>await ws.SendAsync(JsonSerializer.SerializeToUtf8Bytes(value).AsMemory(),WebSocketMessageType.Text,true,ct);
 try{await Wait(Online);var first=await OpenViewer();using var viewer=first.Socket;var frame=await Frame(viewer);using(var image=new Bitmap(new MemoryStream(frame))){var screen=Screen.PrimaryScreen!.Bounds;var p=marker.PointToScreen(new Point(100,60));var color=image.GetPixel((int)((p.X-screen.Left)*(double)image.Width/screen.Width),(int)((p.Y-screen.Top)*(double)image.Height/screen.Height));if(color.R<170||color.B<170||color.G>100)throw new Exception("Real relayed frame did not contain own test marker");}
 if(GetForegroundWindow()!=form.Handle)throw new InvalidOperationException("Foreground changed; unsafe to inject input");target.Focus();target.Clear();var latency=Stopwatch.StartNew();await Send(viewer,new{kind="text",text="محرك NEXORA",seq=1});await Wait(()=>Task.FromResult(target.Text=="محرك NEXORA"));double observedLatency=latency.Elapsed.TotalMilliseconds;
 int clicks=0;EventHandler click=(_,_)=>clicks++;button.Click+=click;try{var p=button.PointToScreen(new Point(50,20));var screen=Screen.PrimaryScreen!.Bounds;await Send(viewer,new{kind="move",x=(p.X-screen.Left)/(double)(screen.Width-1),y=(p.Y-screen.Top)/(double)(screen.Height-1),seq=2});await Send(viewer,new{kind="button",button="left",down=true,seq=3});await Task.Delay(50,ct);await Send(viewer,new{kind="button",button="left",down=false,seq=4});await Wait(()=>Task.FromResult(clicks==1));}finally{button.Click-=click;}
 await Send(viewer,new{type="quality",settings=new{width=640,quality=35,fps=3,monitor=0}});var resized=await Frame(viewer,640);
 await Post("/__test__/drop-agents",new{});await Wait(async()=>!(await Online()));await Wait(Online);var sessions=await Get("/api/sessions");if(sessions.EnumerateArray().First(s=>s.GetProperty("id").GetString()==first.Id).GetProperty("state").GetString()!="ended")throw new Exception("Disconnected session resumed without reauthorization");
 var second=await OpenViewer();using var resumed=second.Socket;await Frame(resumed);using(var end=await http.DeleteAsync("/api/sessions/"+second.Id,ct))end.EnsureSuccessStatusCode();await Wait(async()=>{var all=await Get("/api/sessions");return all.EnumerateArray().First(s=>s.GetProperty("id").GetString()==second.Id).GetProperty("state").GetString()=="ended";});
 return new{realWindowsCapture=true,realBackendRelay=true,realArabicSendInput=true,realMouseClick=true,resolutionScaling=true,agentAutomaticReconnect=true,freshGrantAfterReconnect=true,sessionRevocation=true,observedTextRoundTripMs=observedLatency,latencyMeasurement="WebSocket send to own textbox observation, 50ms polling; not photon latency",sampledFrameBytes=frame.Length+resized.Length,twoWindows=false,serviceWorkerPath=false};
 }finally{engineStop.Cancel();try{await engineTask;}catch(OperationCanceledException){}}
 }
